impl ServerHandler for PersistentTaskServer {
    fn get_task(&self, request: GetTaskParams, context: RequestContext<RoleServer>) -> impl Future<Output = Result<GetTaskResult, McpError>> + MaybeSendFuture + '_ {
        async move {
            let _ = context; // stock Service has already enforced Tasks capability; application auth still must be checked here/store-side
            let detailed: DetailedTask = self.persistent_tasks.get_task(&request.task_id).await?;
            Ok(GetTaskResult::new(detailed))
        }
    }

    fn update_task(&self, request: UpdateTaskParams, context: RequestContext<RoleServer>) -> impl Future<Output = Result<(), McpError>> + MaybeSendFuture + '_ {
        async move {
            let _ = context;
            self.persistent_tasks.update_task(&request.task_id, request.input_responses).await
        }
    }

    fn cancel_task(&self, request: CancelTaskParams, context: RequestContext<RoleServer>) -> impl Future<Output = Result<(), McpError>> + MaybeSendFuture + '_ {
        async move {
            let _ = context;
            self.persistent_tasks.cancel_task(&request.task_id).await
        }
    }
}
